import type { ComboboxInputProps } from "../combobox.types";

import { forwardRef } from "react";
import { ComboboxInput as HeadlessComboboxInput } from "@headlessui/react";
import { clsx } from "clsx";
import { Input } from "@components/input";
import { useMergeRefs } from "@system";

import { useComboboxState } from "../hooks/use-combobox-state";
import { useComboboxInteraction } from "../hooks/use-combobox-interaction";
import { useComboboxFloating } from "../hooks/use-combobox-floating";
import { ComboboxClasses } from "../combobox.styles";

const ComboboxInputComponent = forwardRef<HTMLInputElement, ComboboxInputProps>(
  ({ children, className, id: inputId, ...props }, ref) => {
    const {
      value,
      inputValue,
      setInputValue,
      inputSize,
      placeholder,
      id: rootId,
      variant,
      disabled,
      openOnClick,
      itemToString,
      inputRef,
    } = useComboboxState();
    const mergedRef = useMergeRefs(ref, inputRef);
    const { onQueryChange } = useComboboxInteraction();
    const { setOpen, currentOpenState } = useComboboxFloating();

    return (
      <div style={{ display: "block" }}>
        <HeadlessComboboxInput
          ref={mergedRef}
          as={Input}
          autoComplete="off"
          className={clsx(ComboboxClasses.input, className)}
          disabled={disabled}
          id={inputId || rootId}
          inputSize={inputSize}
          placeholder={placeholder}
          value={inputValue}
          variant={variant}
          onBlur={() => {
            const selectedLabel = itemToString(value);
            if (inputValue !== selectedLabel) {
              setInputValue(selectedLabel);
              onQueryChange?.(selectedLabel);
            }
            setTimeout(() => setOpen(false), 20);
          }}
          onChange={(e) => {
            setInputValue(e.target.value);
            onQueryChange?.(e.target.value);
            setOpen(true);
          }}
          onClick={(e) => {
            if (currentOpenState) {
              e.stopPropagation();
            } else if (openOnClick) {
              setOpen(true);
            }
          }}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown" || e.key === "ArrowUp") {
              setOpen(true);
            }
            if (e.key === "Escape") {
              e.stopPropagation();
              setOpen(false);
            }
            if (e.key === " ") {
              e.preventDefault();
              const newVal = inputValue + " ";
              setInputValue(newVal);
              onQueryChange?.(newVal);
              setOpen(true);
            }
          }}
          {...props}
        >
          {children}
        </HeadlessComboboxInput>
      </div>
    );
  },
);

ComboboxInputComponent.displayName = "Combobox.Input";

export { ComboboxInputComponent as ComboboxInput };
